#!/usr/bin/env bash
# Headless demonstration of milestone M6 against the real pak binary
# (cmd/reminislink/smoke_patch_test.go): a test BPS patch (generated by the
# test encoder, no commercial content) is uploaded to the staging area and
# applied to a 4 MiB ROM as a new file, a patch made for another ROM is
# refused (patch_mismatch), then the patch is applied in place of the ROM
# and the original is found in the trash (replace-rom).
#
# Usage: scripts/smoke-patch.sh
set -euo pipefail
cd "$(dirname "$0")/.."
CGO_ENABLED=0 exec go test -count=1 -v -timeout 5m -run '^TestSmokePatch$' ./cmd/reminislink
